  "settings.cleanupMovedHint": "“Serveropschoning” staat nu in Instellingen › Bibliotheek, bij de andere bibliotheekhulpmiddelen.",
  "settings.cleanupMovedGo": "Bibliotheekhulpmiddelen openen",
  "settings.clearLibraryV2Hint": "Wist de index (nummers, albums, artiesten). Daarmee gaan ook verloren: inhoud van afspeellijsten, waarderingen, bladwijzers, favorieten, handmatig samengestelde boxsets en albumbewerkingen. Er wordt geen muziekbestand verwijderd. Vlak daarvoor wordt een back-up van de database gemaakt. Een scan brengt alleen de nummers terug. Wil je de bibliotheek vernieuwen, start dan liever een volledige scan: die behoudt boxsets en albumbewerkingen.",
  "settings.clearLibraryBusyHint": "Er loopt een scan: wacht tot die klaar is voordat je de bibliotheek leegmaakt.",
  "settings.scanOptions": "Scanopties",
  "settings.qualitySplit": "Albums splitsen op kwaliteit",
  "settings.qualitySplitHint": "Als hetzelfde album in cd- en hi-res-kwaliteit bestaat, twee aparte items maken (bijv. “Album (96kHz/24bit)”)",
  "settings.autoBoxSets": "Automatische boxsets",
  "settings.autoBoxSetsHint": "Schijven in naastgelegen mappen (CD1, CD2…) samenvoegen tot één album en albums met meerdere mappen onder Boxsets plaatsen. Uit: er wordt niets samengevoegd en een album met meerdere schijven verschijnt niet meer onder Boxsets. Al samengevoegde boxsets blijven samengevoegd: “Boxset ongedaan maken” op hun pagina splitst ze weer in hun schijven.",
  "settings.scanImportPlaylists": ".m3u/.pls-afspeellijsten importeren die bij het scannen worden gevonden",
