  "renderer.wav24Hint": "Echte 24-bit-WAV leveren. Standaard aangeboden; alleen geweigerd als de detectietest aantoont dat deze renderer audio/L24 noch audio/wav aankondigt.",
  "renderer.depthCapNotRate": "Let op: het beperken van de bitdiepte beperkt de samplefrequentie niet. Een bestand van 96 kHz/24 bit wordt 96 kHz/16 bit — nog steeds 96 kHz. Kan je renderer maximaal 48 kHz aan, stel dan ook “Max. frequentie” in.",
  "renderer.flacAndWavSplitBySource": "“WAV afdwingen” geldt alleen voor niet-FLAC-bronnen (ALAC, AAC…) — het omzeilt de ALAC-decoder van de renderer. Je FLAC-bestanden worden nog steeds als native FLAC geleverd.",
  "renderer.wav24Unproven": "Er is nog geen detectietest geslaagd: 24 bit blijft beschikbaar, maar niets bevestigt dat dit apparaat het kan lezen. Druk hierboven op “Controleren”.",
  "renderer.wav24Refused": "De detectietest gaf als antwoord: dit apparaat kondigt audio/L24 noch audio/wav aan. 24 bit blijft gesloten — het leveren ervan zou stilte opleveren.",
  "renderer.startDelay": "Startvertraging",
  "renderer.startDelayHint": "Pauze voordat het afspelen start, zodat een DLNA-versterker kan bufferen (helpt als de eerste seconden haperen). 0 = standaard.",
  "renderer.fluxContinu": "Doorlopende stream tussen nummers",
  "renderer.fluxContinuHint": "Voor spelers die twee opeenvolgende nummers slecht aan elkaar koppelen: opeenvolgende nummers van hetzelfde formaat worden als één WAV-stream verzonden, zonder verwerking. Bij de eerste formaatwijziging wordt weer gewoon nummer voor nummer afgespeeld.",
