  "renderer.probeSoapFailed": "De renderer is gevonden, maar het opvragen van de mogelijkheden mislukte. Probeer het opnieuw; als hij al afspeelt, hoef je het netwerk niet aan te passen.",
  "renderer.saveError": "Kon de instelling niet opslaan.",
  "renderer.saveConfig": "Deze configuratie opslaan",
  "renderer.saveConfigHint": "Deze instellingen worden al op het apparaat toegepast zodra je klikt. Deze knop bewaart daarnaast een blijvende kopie die aan dit apparaat is gekoppeld: je kunt die op elk moment vanuit dit scherm terugzetten.",
  "renderer.saveConfigNoKey": "Deze zone heeft geen uitvoer-ID en geen naam: er is niets om een opgeslagen configuratie aan te koppelen.",
  "renderer.configSavedOn": "Configuratie opgeslagen op {date}",
  "renderer.configByName": "Zonder uitvoer-ID is deze configuratie gekoppeld aan de NAAM van de zone: de zone hernoemen zou haar loskoppelen.",
