  "settings.saving": "Opslaan...",
  "settings.status": "Status",
  "settings.unreachable": "Onbereikbaar",
  "settings.notTested": "Niet getest",
  "settings.exportCsv": "CSV exporteren",
  "settings.signIn": "Inloggen",
  "settings.signOut": "Uitloggen",
  "settings.cloudDisconnected": "Uitgelogd bij de cloud",
  "settings.signOutConfirm": "Uitloggen bij je Mozaiklabs-account? Deze server wordt losgekoppeld van het account: de online kopie van de bibliotheek en de Tune Circle-deelacties worden verwijderd, en premiumfuncties die van het account komen stoppen (een licentiesleutel blijft actief). Je kunt daarna opnieuw inloggen.",
  "settings.licenseRateLimited": "Te veel pogingen — wacht een minuut voordat je het opnieuw probeert.",
  "settings.cloudComingSoon": "Cloud binnenkort beschikbaar op deze server",
  "settings.telemetry": "Telemetrie",
  "settings.telemetryHint": "Gebruiksstatistieken versturen om Tune te verbeteren: instantie-ID, versie, platform, bibliotheekomvang, verbonden diensten en apparaatmodellen.",
  "settings.telemetryOffScope": "Uitschakelen stopt ook het delen en downloaden van communitymetadata. De licentievalidatie blijft werken, zodat je Premium nooit kwijtraakt.",
  "settings.communitySync": "Metadata delen met de community",
  "settings.communitySyncHint": "Doe mee aan de verrijking door de community: MusicBrainz-koppeling, genres en credits (componist, dirigent, uitvoerenden) gedeeld tussen Tune-servers. Anoniem — nooit je bestanden.",
  "settings.cloudListens": "Mijn luisterbeurten naar mijn account sturen",
  "settings.cloudListensHint": "Voegt de luisterbeurten van deze server toe aan de pagina “Mijn luisterbeurten” van je account, samen met die van je andere Tune-servers. Per luisterbeurt: de datum, de duur, een ondoorzichtige profiel-ID, de titel, artiest, album en, indien bekend, de ISRC en MusicBrainz-ID. Nooit je bestandspaden, je IP-adres of je zonenamen. Standaard uit.",
  "settings.cloudListensLink": "Mijn luisterbeurten bekijken op mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Je luisterbeurten delen met je mozaiklabs.fr-account?",
  "settings.cloudListensConsentIntro": "Tune kan de luisterbeurten van deze server toevoegen aan je mozaiklabs.fr-account. Er wordt niets verzonden totdat je antwoordt.",
  "settings.cloudListensConsentSentLabel": "Wat wordt verzonden:",
  "settings.cloudListensConsentSent": "per luisterbeurt de datum, de duur, de titel, artiest, album, een ondoorzichtige profiel-ID en, indien bekend, de ISRC- en MusicBrainz-ID’s.",
  "settings.cloudListensConsentNeverLabel": "Wat nooit wordt verzonden:",
  "settings.cloudListensConsentNever": "je bestandspaden, je IP-adres, je zonenamen en je profielnamen.",
  "settings.cloudListensConsentBenefit": "Wat je ervoor terugkrijgt: de pagina “Mijn luisterbeurten”, die de luisterbeurten van al je Tune-servers bundelt, en de luisterbeurten van de community.",
  "settings.cloudListensConsentSettingsReminder": "Je kunt op elk moment van gedachten veranderen via Instellingen › Systeem.",
  "settings.cloudListensConsentError": "Je antwoord kon niet worden opgeslagen. Probeer het opnieuw.",
  "settings.cloudListensConsentNo": "Nee",
  "settings.cloudListensConsentYes": "Ja, delen",
  "settings.cloudListensConsentClose": "Sluiten zonder te antwoorden",
  "settings.communityShare": "Mijn waarderingen en luisterbeurten (anoniem) delen met de community",
  "settings.communityShareHint": "Staat los van “Mijn luisterbeurten” en is standaard uit. Je albumwaarderingen (zonder commentaar) en de luisterbeurten die je account NA het inschakelen ontvangt, gaan op in openbare, anonieme totalen, die op een albumpagina verschijnen vanaf drie verschillende personen. Er worden nooit individuele gegevens getoond. Uitschakelen verwijdert je bijdrage direct.",
  "settings.communityMeasuresReceive": "Analyseresultaten van de community ontvangen",
  "settings.communityMeasuresReceiveHint": "Standaard uit. Voor je FLAC-bestanden vraagt de server mozaiklabs.fr om ReplayGain, dynamisch bereik en akoestische vingerafdrukken die al op precies hetzelfde signaal zijn gemeten door minstens twee andere installaties. Ze vullen alleen aan wat ontbreekt: je tags en je eigen metingen worden nooit vervangen. De site ontvangt alleen een kort voorvoegsel, nooit de lijst van je bestanden.",
  "settings.communityMeasuresContribute": "Mijn analyseresultaten delen met de community",
  "settings.communityMeasuresContributeHint": "Standaard uit. De server stuurt de site alleen de metingen die hij zelf op je FLAC-bestanden heeft gedaan (ReplayGain, dynamisch bereik, akoestische vingerafdruk), herkenbaar aan de signatuur van hun signaal. Er wordt geen pad, titel, bestandsnaam of account verzonden: de server identificeert zich met zijn installatienummer. Uitschakelen wist wat al is verzonden.",
  "library.communityRating": "★ {average} ({count} waarderingen)",
  "library.communityListens": "Luisterbeurten: {count}",
  "library.communityListensTip": "Luisterbeurten in de Tune-community",
  "library.communityLine": "{parts} in de community",
  "settings.communityContribution": "Mijn verrijkte metadata delen met de community",
  "settings.communityNeedsTelemetry": "Geen effect zolang telemetrie uit staat: delen heeft het nodig, maar telemetrie alleen schakelt delen niet in.",
  "settings.telemetryEnvLocked": "Vergrendeld door de beheerder: TUNE_TELEMETRY=false zet telemetrie uit voor de hele machine, en niets in dit scherm kan het weer aanzetten.",
  "settings.cloudRateLimitPaused": "Sommige cloudsynchronisaties zijn tijdelijk gepauzeerd om de limieten van de server te respecteren.",
  "settings.cloudRetryIn": "Automatisch opnieuw proberen over",
