  "cloudBackup.title": "Cloudback-up",
  "cloudBackup.intro": "Tune maakt een back-up van je aanpassingen bij Mozaiklabs, versleuteld op deze server met een sleutel die Mozaiklabs niet kent: instellingen, zones, profielen en voorkeuren, equalizers, favorieten, afspeellijsten en radiozenders. Nooit je bibliotheek, en ook geen wachtwoorden en tokens van diensten, met één uitzondering: het Discogs-token, dat versleuteld met de rest meegaat. Er worden hooguit drie momentopnamen per machine en vijf machines per account bewaard; de oudste worden verwijderd.",
