  "upsampling.eyebrow": "Premium-plug-in",
  "upsampling.title": "Upsampling",
  "upsampling.lead": "Verhoogt de frequentie van de bron naar de hoogste frequentie die de DAC accepteert, binnen dezelfde familie (44,1 → 352,8 kHz, 48 → 384 kHz), op de lokale uitvoer. Het niveau wordt 3 dB verlaagd, en een veiligheidslimiter houdt de zeldzame resterende pieken tegen: geen clipping.",
  "upsampling.noZone": "Kies een zone om de upsampling ervan in te stellen.",
  "upsampling.bitPerfect": "Wanneer upsampling actief is, verandert elke sample: het pad is niet meer bit-perfect. De PURE-modus omzeilt het altijd, en een DoP-stream wordt nooit geüpsampled.",
  "upsampling.enabled": "Deze zone upsamplen",
  "upsampling.enabledHint": "Standaard uit. Alleen lokale uitvoer, in gedeelde modus, op een DAC waarvan de frequenties gemeten zijn.",
  "upsampling.filter": "Filter",
  "upsampling.filterHint": "Alleen de filters die deze machine in realtime draait (met een marge van ×3) worden aangeboden. Tussen haakjes: de niveauverlaging.",
  "upsampling.filterNotAdmitted": "Deze machine kan dit filter niet in realtime draaien: het wordt niet toegepast. Kies een ander of meet de machine opnieuw.",
  "upsampling.target": "Doelfrequentie",
  "upsampling.targetHint": "Een geheel veelvoud van de bron, nooit hoger dan wat de DAC accepteert.",
